// Получаем входящие данные
const inputData = $input.all();

// Собираем все проекты из всех входящих элементов
let allProjects = [];

inputData.forEach(item => {
  let projects;

  // Проверяем, является ли item.json массивом или содержит массив
  if (Array.isArray(item.json)) {
    projects = item.json;
  } else if (item.json && Array.isArray(item.json.projects)) {
    projects = item.json.projects;
  } else {
    // Если это один объект, делаем из него массив
    projects = [item.json];
  }

  // Добавляем все проекты в общий массив
  allProjects = allProjects.concat(projects);
});

// Извлекаем названия проектов для списка
const projectNames = allProjects.map(project => project.project_name);

// Формируем строку со списком проектов
const projectsList = "Список проектов: " + projectNames.join(", ");

// Формируем единый текст для всех проектов
let fullText = '';

allProjects.forEach((project, index) => {
  if (index > 0) {
    fullText += '\n\n'; // Отступ между проектами
  }

  // Заголовок проекта
  fullText += `Проект "${project.project_name}"\n`;

  // Основные поля проекта

  fullText += `doc: ${project.doc}\n`;

  // Поля storyboard
  if (project.storyboard_client && project.storyboard_client !== null) {
    fullText += `storyboard_client: ${project.storyboard_client}\n`;
