return [{
  json: {
    projects_details: fullText,
    projects_list: projectsList
  }
}];

// Получаем входные данные
const inputData = $input.all();

// Массив для результатов
const outputItems = [];

// Обрабатываем каждый входной item
for (const item of inputData) {
  // Получаем текст из поля text
  let text = item.json.text || '';

  // Сначала разделяем по разделителю "---"
  const parts = text.split('---');

  // Обрабатываем каждую часть
  for (const part of parts) {
    // Убираем все символы \n и лишние пробелы
    let cleanText = part.replace(/\\n/g, '').replace(/\n/g, '').trim();

    // Если текст не пустой
    if (cleanText) {
      // Проверяем, содержит ли строка двоеточие (например, "doc:", "storyboard_client:")
      if (cleanText.includes(':')) {
        // Разделяем по двоеточию
        const colonParts = cleanText.split(':');

        // Первая часть - это категория (например, "doc", "storyboard_client")
        const category = colonParts[0].trim();
        if (category) {
          outputItems.push({
            json: {
              text: category
            }
          });
        }

        // Остальная часть - это содержание после двоеточия
        const content = colonParts.slice(1).join(':').trim();
        if (content) {
          outputItems.push({
            json: {
              text: content
            }
          });
        }
      } else {
        // Если нет двоеточия, просто добавляем как есть
        outputItems.push({
          json: {
            text: cleanText
          }
        });
      }
    }
  }
}

return outputItems;
